def predict(x, y):
  lhs = x.T if args.transpose_lhs else x
  if args.int8:
    return jnp.matmul(lhs, y, preferred_element_type=jnp.int32)
  if args.bf16:
    return jnp.matmul(lhs, y, preferred_element_type=jnp.float32)
  return lhs @ y

